import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.CJruDB7H.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"sidebar_position":1},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),r={name:"guide/introduction.md"};function i(s,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Some screens are hard to build because the backend will not cooperate. The empty list that a real account grows out of in a day. The session that expires halfway through a form. The plan that has run out of seats. The response that takes three seconds. You can reach each of them by editing a handler, reloading, and editing it back — which is why most people check them once and hope.</p><p>Mocking GUI puts a panel on top of <a href="https://mswjs.io" target="_blank" rel="noreferrer">MSW</a> so you can reach them from the running app instead. Pick a different response for an endpoint and the screen follows; your code never moves.</p><blockquote><p>Prefer to see it rather than read it? The <a href="/mocking-gui/demo/" target="_blank" rel="noreferrer">live demo ↗</a> is a real app with no server behind it — open the panel, change what an endpoint returns, and watch the screen follow.</p></blockquote><h2 id="what-it-changes" tabindex="-1">What it changes <a class="header-anchor" href="#what-it-changes" aria-label="Permalink to &quot;What it changes&quot;">​</a></h2><p>Without it, the states above live in code: an error you temporarily hard-code, a delay you add and forget to remove, a fixture you edit to be empty. With it they live in a panel, which has three consequences worth the setup.</p><p><strong>You can check the states you would otherwise skip.</strong> Error, empty and loading stop being a detour and become a dropdown, so they get looked at as often as the happy path.</p><p><strong>A bug can be handed over instead of described.</strong> A scenario captures several endpoints at once — payment declined <em>and</em> metrics degraded <em>and</em> alerts unread — as one code you paste into a ticket. Whoever opens it lands in the state you were in.</p><p><strong>The server sees the same mocks.</strong> Panel state is mirrored into a cookie, so a Next.js server component renders against what the browser is showing rather than against the real API.</p><h2 id="what-it-is-technically" tabindex="-1">What it is, technically <a class="header-anchor" href="#what-it-is-technically" aria-label="Permalink to &quot;What it is, technically&quot;">​</a></h2><p>It is a layer over MSW, not a replacement for it. Handlers you already have keep working; the panel reads them and gives you a way to drive them.</p><ul><li>Built on MSW 2.x&#39;s <code>http</code> namespace.</li><li>Intercepts <code>fetch</code>, <code>XMLHttpRequest</code> and the rest, across <code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>PATCH</code> and <code>DELETE</code>.</li><li>Responses can be a fixed list of variants, a function of the request, or generated from an OpenAPI document.</li><li>The panel renders in a Shadow DOM, so none of its styles reach your app.</li></ul><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Ready to introduce Mocking GUI to your project?</p><p>👉 <strong><a href="./quick-start.html">Installation &amp; Setup Guide</a></strong> - Get started in 3 minutes with detailed installation instructions and framework integration examples.</p><p>For advanced usage:</p><ul><li><strong><a href="./usage/swagger-guide.html">Swagger Automation</a></strong> - Connect your existing API docs for instant mock generation</li><li><strong><a href="./usage/api-guide.html">Usage Guides</a></strong> - Learn about handlers, scenarios, and advanced features</li></ul>',17)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
